// ru message catalog, typed `Partial<Record<MessageId, string>>`:
// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/ru.md. Neutral modern Russian,
// addressing the reader as lowercase вы; buttons in the infinitive; sentence
// case; «» quotes; product nouns are Russian (агент, компьютер, сервер) and
// brand forms (Raft, Raft Computer, Raft Desktop, …) stay Latin. Plurals use
// `one`, `few`, `many` and `other`; placeholders never sit where Russian
// would decline them.

