  "settings.slackBridge.managePairs": "Управлять сопоставлением каналов",
  "settings.slackBridge.disconnect": "Отключить рабочее пространство Slack",
  "settings.slackBridge.privateReauthorizationHint": "Чтобы выбрать закрытые каналы Slack, администратор сервера должен обновить авторизацию Slack с аккаунта, который состоит в этих каналах.",
  "settings.slackBridge.authorizerMissingTitle": "Для закрытых каналов нужна новая авторизация Slack",
  "settings.slackBridge.authorizerMissingDescription": "Это подключение было авторизовано до того, как Raft начал записывать, кто выполнил авторизацию. Поэтому Raft не может подтвердить, что этому пользователю видны связанные закрытые каналы, и синхронизация этих пар остановлена. Повторная проверка не поможет. Обновите авторизацию Slack с аккаунта, который состоит в этих каналах.",
  "settings.slackBridge.authorizerMissingReadOnly": "Это подключение было авторизовано до того, как Raft начал записывать, кто выполнил авторизацию. Поэтому Raft не может подтвердить, что этому пользователю видны связанные закрытые каналы, и синхронизация этих пар остановлена. Владелец или администратор сервера должен обновить авторизацию Slack с аккаунта, который состоит в этих каналах.",
  "settings.slackBridge.reauthorize": "Обновить авторизацию Slack",
  "settings.slackBridge.oauthReturn.title": "Авторизация Slack не завершена",
  "settings.slackBridge.oauthReturn.cancelled": "Авторизация была отменена или отклонена в Slack. Ничего не изменилось — можно попробовать ещё раз.",
  "settings.slackBridge.oauthReturn.retryable": "Slack был временно недоступен. Ничего не изменилось — попробуйте ещё раз через несколько минут.",
  "settings.slackBridge.oauthReturn.unconfirmed": "Raft не удалось подтвердить, завершил ли Slack авторизацию. Обновите страницу через минуту и проверьте текущее состояние, прежде чем пробовать снова.",
  "settings.slackBridge.oauthReturn.identityConflict": "Вы авторизовали другое рабочее пространство Slack (или приложение), а не то, к которому уже подключён этот сервер Raft. Авторизуйте то же рабочее пространство или сначала отключите его.",
  "settings.slackBridge.oauthReturn.failed": "Авторизация Slack не завершена, ничего не изменилось. Попробуйте ещё раз; если ошибка повторяется, обратитесь в поддержку Raft и укажите код {code}.",
  "settings.slackBridge.disconnectDescription": "При отключении отзываются учётные данные Slack этого сервера Raft, все сопоставления каналов, авторизации на отправку и связи аккаунтов. Приложение в Slack при этом не удаляется; для повторного подключения потребуется новая авторизация.",
