  "settings.slackBridge.mentionCleanupTitle": "Некоторые старые группы для упоминаний в Slack ещё не удалены",
  "settings.slackBridge.mentionCleanupPending": "Текущие участники уже доступны в меню @ в Slack. Некоторые старые или повторяющиеся группы ещё не удалены. Raft попробует снова; если Slack не даст их отключить, это может понадобиться сделать администратору Slack. На синхронизацию сообщений это не влияет.",
  "settings.slackBridge.mentionSyncTitle": "Некоторых участников пока нельзя выбрать в меню @ в Slack",
  "settings.slackBridge.mentionSyncRestricted": "Сообщения синхронизируются как обычно, а упоминание через @имя участника Raft, введённое в Slack, дойдёт до адресата, если ни у кого другого в канале нет такого же имени. Чтобы эти участники появились и в меню @ в Slack, администратор Slack должен разрешить участникам создавать группы пользователей: Workspace settings → Permissions → User groups.",
  "settings.slackBridge.mentionSyncMissingScope": "Сообщения синхронизируются как обычно, а упоминание через @имя участника Raft, введённое в Slack, дойдёт до адресата, если ни у кого другого в канале нет такого же имени. Чтобы эти участники появились и в меню @ в Slack, Raft нужно ещё одно разрешение Slack: нажмите «Обновить авторизацию Slack» ниже.",
  "settings.slackBridge.mentionSyncNameTaken": "Сообщения синхронизируются как обычно, а упоминание через @имя участника Raft, введённое в Slack, дойдёт до адресата, если ни у кого другого в канале нет такого же имени. Не удалось добавить в меню @ в Slack {count, plural, one {# участника} few {# участников} many {# участников} other {# участника}}: все имена, которые пробовал Raft, в Slack уже заняты. Чтобы это исправить, переименуйте их в Raft или освободите имя в Slack.",
  "settings.slackBridge.mentionSyncGeneric": "Сообщения синхронизируются как обычно, а упоминание через @имя участника Raft, введённое в Slack, дойдёт до адресата, если ни у кого другого в канале нет такого же имени. Slack отказался добавить некоторых из них в меню @ ({code}); Raft продолжает попытки.",
