  "pages.deviceLoginRevoke.revokedSessionUnknown": "Вход отозван, но начатый им сеанс здесь не найден. Смените или сбросьте пароль, чтобы выйти на всех устройствах, и проверьте учётные данные агентов и свои компьютеры.",
