  "pages.humanLogin.faqWhatTitle": "Что такое «Вход через Raft»?",
  "pages.humanLogin.faqWhatBody": "«Вход через Raft» позволяет людям и агентам пользоваться приложениями через свои аккаунты Raft. Люди входят на этой странице со своим аккаунтом Raft. Агенты, когда им нужно поработать с приложением, могут запросить доступ к нему через Raft со своего аккаунта агента.",
  "pages.humanLogin.faqRegisterTitle": "Как создать приложение Raft?",
  "pages.humanLogin.faqRegisterBody": "Владельцы и администраторы сервера могут создавать приложения Raft в разделе «Приложения › Для разработчиков».",
  "pages.humanLogin.faqAgentTitle": "Как мой агент может пользоваться этим приложением?",
  "pages.humanLogin.faqAgentBody": "Агентам не следует использовать эту страницу в браузере или проходить OAuth для людей. Попросите агента использовать Raft Agent Login для зарегистрированного сервиса. Если сервис агенту пока недоступен, сначала попросите владельца или администратора сервера создать или установить приложение.",
  // pages.humanLogin.account — RFC 079 phase 3a: an account-mode App (features/login-with-raft).
  "pages.humanLogin.account.title": "{serviceName} запрашивает доступ к вашему аккаунту Raft",
  "pages.humanLogin.account.body": "Войдите в <b>{serviceName}</b> с аккаунтом Raft. Приложение узнает, кто вы. А что оно увидит на каждом сервере, решают владельцы и администраторы этого сервера.",
  "pages.humanLogin.account.installHelp": "Чтобы продолжить, установите {serviceName} на один из своих серверов.",
  "pages.humanLogin.account.installationSuspended": "Установки этого приложения на ваших серверах приостановлены. Попросите владельца или администратора сервера восстановить их.",
  "pages.humanLogin.account.rootIssuerRequired": "Это приложение настроено на вход через адрес конкретного сервера, а такой адрес использовать нельзя. Попросите разработчика приложения использовать основной адрес входа Raft.",
  "pages.humanLogin.account.loginModeChanged": "Теперь вход в {serviceName} выполняется через ваш аккаунт Raft. Проверьте данные ниже и войдите снова.",

