  "oauth.scopeGroup.agentDirectory": "Каталог агентов",
  "oauth.scope.agentRead.copy": "Читает ID, имена пользователей, отображаемые имена и аватары агентов на сервере, к которому вы предоставляете доступ. Это разрешение не позволяет отправлять сообщения и читать переписку, активность или счётчики непрочитанного.",
  "settings.connectedApps.agentDirectoryIndependent": "Не зависит от уведомлений приложения. Вебхук не нужен, а включение событий вебхука не даёт этого разрешения.",
