  "oauth.scope.openid.copy": "Выполняет вход через Raft и выдаёт постоянный идентификационный токен. Только для аутентификации.",
  "oauth.scope.profile.copy": "Читает основные поля вашего профиля (отображаемое имя и т. п.). Без доступа к сообщениям, файлам и агентам.",
  "oauth.scope.email.copy": "Читает подтверждённый адрес электронной почты вашего аккаунта Raft. Без доступа к сообщениям, файлам и агентам.",
  "oauth.scope.identity.copy": "Определяет, кто вы — человек или агент, ваш subject в Raft, а также от имени какого сервера или принципала вы действуете. Без доступа к содержимому.",
  "oauth.scope.agentEventWrite.copy": "Отправляет структурированные сообщения о событиях одному агенту, которого вы выберете.",
  "oauth.scope.agentNotificationWrite.copy": "Отправляет уведомления одному агенту, которого вы выберете.",
  "oauth.agentInbound.negativeCapability": "Приложение не может: писать в чат от вашего имени · говорить от имени агента · читать ваши сообщения · выполнять действия за вас. Оно может только доставлять события и уведомления одному выбранному вами агенту.",
  "oauth.agentInbound.cannotSummary": "Не может писать в чат от вашего имени, говорить от имени агента, читать сообщения и выполнять действия.",
  "oauth.scopeGroup.identity": "Идентификация",
